export function render(parsed, definitions) {
  const out = []
  for (const block of parsed) {
    if (block.kind === 'heading') {
      out.push(`<h${block.level}>${renderInline(block.text, definitions)}</h${block.level}>`)
    } else if (block.kind === 'paragraph') {
      const lines = block.lines.map(line => renderInline(line, definitions)).join('\n')
      out.push(`<p>${lines}</p>`)
    } else if (block.kind === 'fence') {
      const content = block.content.map(line => escapeText(line)).join('\n')
      if (block.info) {
        out.push(`<pre><code class="language-${escapeText(block.info)}">${content}\n</code></pre>`)
      } else {
        out.push(`<pre><code>${content}\n</code></pre>`)
      }
    } else if (block.kind === 'list') {
      out.push(renderList(block.items, definitions))
    }
  }
  return out.length === 0 ? '' : out.join('\n') + '\n'
